package com.pocketmusic.android;
import android.app.*;
import android.content.*;
import java.io.File;
import java.util.*;
final class DownloadNotifications {
 static final int ACTIVE=20,RESULT=21;
 static PendingIntent open(Context c,boolean downloads){return PendingIntent.getActivity(c,downloads?20:22,new Intent(c,MainActivity.class).setAction(downloads?"com.pocketmusic.OPEN_DOWNLOADS":"com.pocketmusic.OPEN_LIBRARY").addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_SINGLE_TOP).putExtra(downloads?"downloads":"library",true),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 static Notification active(Context c,List<DownloadQueue.Job> jobs){List<DownloadQueue.Job> pending=new ArrayList<>();for(DownloadQueue.Job j:jobs)if(j.pending())pending.add(j);String title=pending.size()==1?pending.get(0).title:"Pocket Music downloads";String text=DownloadPresentation.summary(pending);if(pending.size()==1){DownloadQueue.Job j=pending.get(0);text=DownloadPresentation.state(j)+" · "+j.format.toUpperCase(Locale.ROOT);String transfer=DownloadPresentation.transfer(j);if(!transfer.isEmpty())text+=" · "+transfer;}
  Notification.InboxStyle expanded=new Notification.InboxStyle().setBigContentTitle(title).setSummaryText("Tap to manage downloads");for(int i=0;i<Math.min(5,pending.size());i++){DownloadQueue.Job j=pending.get(i);expanded.addLine(j.title+" — "+DownloadPresentation.state(j));}
  PendingIntent cancel=PendingIntent.getForegroundService(c,21,new Intent(c,DownloadService.class).setAction("cancel"),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);
  return new Notification.Builder(c,"downloads").setSmallIcon(R.drawable.ic_lucide_download).setContentTitle(title).setContentText(text).setSubText("Pocket Music").setStyle(expanded).setContentIntent(open(c,true)).setOnlyAlertOnce(true).setShowWhen(false).setOngoing(true).setCategory(Notification.CATEGORY_PROGRESS).setProgress(100,DownloadPresentation.progress(jobs),DownloadPresentation.unknown(jobs)).addAction(new Notification.Action.Builder(null,"View downloads",open(c,true)).build()).addAction(new Notification.Action.Builder(null,"Cancel all",cancel).build()).build();
 }
 static Notification finished(Context c,List<DownloadQueue.Job> jobs){int done=0,attention=0;DownloadQueue.Job retry=null;for(DownloadQueue.Job j:jobs){if("done".equals(j.state))done++;else if(DownloadPresentation.group(j).equals("attention")){attention++;retry=j;}}if(done+attention==0)return null;String title=attention>0?attention+" download"+(attention==1?" needs":"s need")+" attention":done==1?"Download ready":"Downloads ready";String text=jobs.size()==1?jobs.get(0).title:DownloadPresentation.summary(jobs);
  Notification.Builder builder=new Notification.Builder(c,"download-results").setSmallIcon(attention>0?R.drawable.ic_lucide_download:R.drawable.ic_lucide_check).setContentTitle(title).setContentText(text).setStyle(new Notification.BigTextStyle().bigText(text+(attention>0?"\nOpen Downloads to retry or fix the save folder.":"\nSaved music is available in your library."))).setAutoCancel(true).setContentIntent(open(c,attention>0)).setCategory(Notification.CATEGORY_STATUS);
  if(retry!=null){PendingIntent action=PendingIntent.getForegroundService(c,retry.key.hashCode(),new Intent(c,DownloadService.class).setAction("retry").putExtra("job",retry.key),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);builder.addAction(new Notification.Action.Builder(null,"Retry",action).build());}else{builder.addAction(new Notification.Action.Builder(null,"Open library",open(c,false)).build());if(jobs.size()==1){DownloadQueue.Job job=jobs.get(0);File file=MusicRepository.downloaded(c,job.id,job.format);if(file!=null&&TrackFiles.audio(file)){PendingIntent play=PendingIntent.getForegroundService(c,23,new Intent(c,LocalPlayerService.class).putExtra("path",file.getAbsolutePath()),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);builder.addAction(new Notification.Action.Builder(null,"Play",play).build());}}}return builder.build();
 }
}
